mapper.select:
WITH old AS MATERIALIZED (
  SELECT pay_id,pay_plan_dt FROM fin.pay WHERE pay_ym=#{month} AND pay_odr_no=#{order.pay_odr_no}
    AND pay_stts_cd='PLAN' AND pay_plan_dt <> #{order.planned_date} FOR UPDATE
), changed AS (
  UPDATE fin.pay p SET pay_plan_dt=#{order.planned_date},updated_at=CURRENT_TIMESTAMP,updated_by=#{actor}
  FROM old WHERE p.pay_id=old.pay_id RETURNING p.pay_id
), history AS (
  INSERT INTO sys.data_chg_hist(tbl_nm,obj_rec_id,data_chg_ty_cd,clmn_nm,bfr_val,aft_val,chg_user_id)
  SELECT 'fin.pay',old.pay_id::text,'UPDATE','pay_plan_dt',old.pay_plan_dt::text,
    CAST(#{order.planned_date} AS text),#{actor} FROM old JOIN changed USING(pay_id) RETURNING data_chg_hist_id
) SELECT COUNT(*)::int FROM history
